import math
def priority(task, state, p=1.0, c=1.0, k=1.0, m=2.0, a=1.0, b=1.0, g=1e9):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    mean_est = max(state.mean_est, 1e-6)
    ratio = wait / est
    pressure = state.queue_work / max(state.capacity * mean_est, 1e-6)
    if pressure > p:
        guard = g if ratio >= c else 0.0
        return guard + (1.0 + a * task.weight) / est * (1.0 + b * ratio)
    slack = max(0.0, task.due - est - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    return tier * task.weight / est * math.exp(-slack / max(k * mean_est, 1e-6))  # tuned (p=1.07,c=0.489,k=1.85,m=5.84,a=2.89,b=0.338,g=5.61e+08)

import math
def priority(task, state, k=1.0, m=5.0, b=0.3, c=0.8, q=0.01, r=0.01):
