    now = state.now
    mean = max(state.mean_est, 1e-6)
    slack = task.due - now - est
    weight = max(task.weight, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    wait = max(0.0, now - task.release)
    if slack <= c * mean:
        base = -max(task.due, now + est)
        urgency = tier * weight / est * math.exp(-max(0.0, slack) / max(k * mean, 1e-6))
        return base + b * urgency * (1.0 + wait / est)
    else:
