import math
def priority(task, state, b=1.0, k=4.0, q=8.0, m=1.0, h=1.0):
    p = max(task.estimated_runtime, 1e-6)
    now = state.now
    wait = max(0.0, now - task.release)
    slack = max(0.0, task.due - p - now)
    mean = max(state.mean_est, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    if state.queue_len > q:
        return tier * (task.weight / p) * (1.0 + b * wait / p)
    atc = (task.weight / p) * math.exp(-slack / max(k * mean, 1e-6))
    return tier * atc * (1.0 + h * wait / p)
